CREATE OR REPLACE FUNCTION public.generate_uid()
RETURNS text
LANGUAGE plpgsql
AS $function$
DECLARE
    letters TEXT := 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
    allowed_chars TEXT := '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
    uid TEXT := '';
    i INT;
BEGIN
    uid := substr(letters, floor(random() * length(letters) + 1)::int, 1);

    FOR i IN 1..10 LOOP
        uid := uid || substr(allowed_chars, floor(random() * length(allowed_chars) + 1)::int, 1);
    END LOOP;

    RETURN uid;
END;
$function$;
